9	type OrbState = "connecting" | "listening" | "muted" | "thinking" | "speaking" | "idle";
10	const ORB_TONES: Record<OrbState, string> = {
11	  connecting: "[--orb-a:var(--color-ai-border)] [--orb-b:var(--color-ai-soft)]",
12	  listening: "[--orb-a:var(--color-ai)] [--orb-b:var(--color-ai-border)]",
13	  muted: "[--orb-a:var(--color-subtle)] [--orb-b:var(--color-muted)]",
14	  thinking: "[--orb-a:var(--color-ai)] [--orb-b:var(--color-lime)]",
15	  speaking: "[--orb-a:var(--color-lime)] [--orb-b:var(--color-brand)]",
16	  idle: "[--orb-a:var(--color-input)] [--orb-b:var(--color-muted)]",
17	};
