19	/** The orb follows whoever is talking: its glow and ring swell with the voice, it turns while Moneo works, and it holds still for reduced motion. */
20	function Orb({ levels, state }: { levels: () => { mic: number; moneo: number }; state: OrbState }) {
21	  const orb = useRef<HTMLDivElement>(null);
22	  useEffect(() => {
23	    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
24	    let frame = 0, smooth = 0;
25	    const tick = () => {
26	      const { mic, moneo } = levels();
27	      smooth += (Math.max(mic, moneo) - smooth) * 0.2;
28	      orb.current?.style.setProperty("--level", smooth.toFixed(3));
29	      frame = requestAnimationFrame(tick);
30	    };
31	    frame = requestAnimationFrame(tick);
32	    return () => cancelAnimationFrame(frame);
33	  }, [levels]);
34	  const still = state === "idle" || state === "muted";
35	  return <div ref={orb} aria-hidden="true" className={`relative grid size-36 shrink-0 place-items-center sm:size-52 ${ORB_TONES[state]}`}>
36	    <div className="absolute inset-2 rounded-full bg-[radial-gradient(circle,var(--orb-a),transparent_68%)] opacity-45 blur-2xl" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.5))" }} />
37	    <div className="absolute inset-4 rounded-full border sm:inset-5 border-[color-mix(in_oklab,var(--orb-a)_40%,transparent)]" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.3))" }} />
38	    <div className={still ? "" : "motion-safe:animate-orb-breathe"}>
39	      <div className="relative size-24 overflow-hidden rounded-full shadow-[inset_0_-10px_30px_rgb(0_0_0/0.18),0_14px_40px_-14px_var(--orb-a)] sm:size-32" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.14))" }}>
40	        <div className={`absolute -inset-1/4 blur-md bg-[conic-gradient(from_90deg,var(--orb-a),var(--orb-b),var(--orb-a))] ${state === "thinking" || state === "connecting" ? "motion-safe:animate-orb-spin" : ""}`} />
41	        <div className="absolute inset-0 rounded-full bg-[radial-gradient(circle_at_32%_28%,rgb(255_255_255/0.5),transparent_48%)]" />
42	      </div>
43	    </div>
44	  </div>;
45	}
46	
47	/** A live voice call with Moneo: speak or type, see the requests it is working on, and tap the cards it makes. The full transcript is saved with the call. */
48	export function VoiceCall({ conversationId, onAnswer, onEnded, onClose }: { conversationId: string; onAnswer: (question: string, answer: ChatAnswer) => void; onEnded: () => void; onClose: () => void }) {
49	  return <VoiceCallView call={useVoiceCall(conversationId, onAnswer, onEnded)} onClose={onClose} />;
50	}
51	
52	/** The call screen for a call's state, kept apart from the connection so each state can be rendered alone. */
53	export function VoiceCallView({ call, onClose }: { call: ReturnType<typeof useVoiceCall>; onClose: () => void }) {
54	  const [text, setText] = useState("");
55	  const body = useRef<HTMLDivElement>(null);
56	  useEffect(() => { body.current?.scrollTo({ top: body.current.scrollHeight }); }, [call.tasks]);
57	  const live = call.status === "live";
58	  const open = live || call.status === "connecting";
59	  const state: OrbState = call.status === "connecting" ? "connecting" : !live ? "idle" : call.talking ? "speaking" : call.thinking ? "thinking" : call.muted ? "muted" : "listening";
60	  const label = { connecting: "Connecting…", listening: "Listening", muted: "You're muted", thinking: "Working on it", speaking: "Moneo is talking", idle: call.status === "ended" ? "Call ended" : "Call dropped" }[state];
61	  const running = call.tasks.filter(task => task.status === "running");
62	  const round = "grid size-16 place-items-center rounded-full transition-[background-color,transform] active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai disabled:opacity-40";
63	
64	  return <section role="dialog" aria-modal="true" aria-label="Voice call with Moneo" className="fixed inset-0 z-50 flex flex-col bg-background lg:sticky lg:top-19 lg:z-auto lg:h-[calc(100dvh-4.75rem)]">
65	    <header className="flex items-center justify-between gap-3 border-b border-border px-4 pt-[max(0.75rem,env(safe-area-inset-top))] pb-3 sm:px-8 lg:pt-3">
66	      <p className="font-display text-lg font-semibold">Call with Moneo</p>
67	      {live && <span className="inline-flex items-center gap-1.5 rounded-full bg-success-soft px-2.5 py-1 text-xs font-medium text-success"><span className="size-1.5 rounded-full bg-current motion-safe:animate-pulse" aria-hidden="true" />Live</span>}
68	    </header>
69	    <div ref={body} className="mx-auto flex min-h-0 w-full max-w-[720px] flex-1 flex-col overflow-y-auto px-4 sm:px-8">
70	      <div className="flex flex-col items-center pt-4 sm:pt-8">
71	        <Orb levels={call.levels} state={state} />
72	        <p role="status" className="flex h-7 items-center gap-2 font-display text-lg font-medium">{state === "connecting" && <Loader2 className="size-4 text-ai motion-safe:animate-spin" aria-hidden="true" />}{label}</p>
73	      </div>
74	      {call.error && <p role="alert" className="mt-4 flex items-start gap-2 rounded-xl border border-danger/30 bg-danger-soft px-3.5 py-2.5 text-sm text-danger"><AlertCircle className="mt-0.5 size-4 shrink-0" aria-hidden="true" />{call.error}</p>}
75	      {!call.tasks.length && live && <p className="mt-6 text-center text-[15px] text-muted-foreground sm:text-base">Say hi, ask about your money, or tell Moneo what you spent.</p>}
76	      {call.tasks.length > 0 && <div className="mt-5">
77	        <p className="eyebrow pb-2">{running.length ? `Working on ${running.length} of ${call.tasks.length}` : "All done"}</p>
78	        <ul className="space-y-1.5" aria-label="Tasks">
79	          {call.tasks.slice(-6).map(task => <li key={task.requestId} className="flex min-h-14 items-center gap-3 rounded-xl border border-border bg-card py-1.5 pr-1 pl-3.5 text-sm">
80	            <TaskIcon status={task.status} />
81	            <span className="min-w-0 flex-1"><span className="block truncate font-medium">{task.text}</span><span className={`block text-xs ${task.status === "failed" ? "text-danger" : "text-muted-foreground"}`}>{task.step}</span></span>
82	            {(task.status === "running" || call.unsaid.has(task.requestId)) && <button type="button" onClick={() => void call.cancel(task.requestId)} aria-label={`Stop “${task.text}”`} className="grid size-11 shrink-0 place-items-center rounded-lg text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ai"><X className="size-4" aria-hidden="true" /></button>}
83	          </li>)}
84	        </ul>
85	      </div>}
86	      {call.cards.length > 0 && <div aria-label="Cards to review" role="region" className="mt-5">
87	        <p className="eyebrow">Tap to save · nothing is saved until you do</p>
88	        {call.cards.map(id => <IouCard key={id} id={id} />)}
89	      </div>}
90	      <div className="h-4 shrink-0" />

