30	export function TradeCard({ id, proposal, locale = "en-GB", onChange }: { id: string; proposal: Proposal; locale?: string; onChange: (next: Proposal) => void }) {
31	  const [error, setError] = useState<string>();
32	  const [pending, start] = useBusy();
33	  const { trade } = proposal;
34	  const seconds = useSecondsLeft(trade.expiresAt);
35	  const { money, dateTime } = displayFormat(locale, Intl.DateTimeFormat().resolvedOptions().timeZone);
