41	    setError(undefined);
42	    try {
43	      const [outcome] = await decideAgentProposals([id], decision);
44	      if (outcome.status === "unknown") onChange({ ...proposal, status: "applying", result: { error: outcome.error, unknown: true } });
45	      else if (outcome.error) { setError(outcome.error); onChange({ ...proposal, status: "failed" }); }
46	      else onChange({ ...proposal, status: decision === "accept" ? "accepted" : "rejected" });
47	    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not reach Moneo. Nothing was sent."); }
48	  });
49	  const tone = trade.action === "buy" ? "bg-success-soft text-success" : trade.action === "sell" ? "bg-danger-soft text-danger" : "bg-muted text-foreground";
50	  const clock = seconds === null ? null : `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
51	  const figures: [string, string][] = trade.action === "cancel"
52	    ? [["Shares", trade.shares ?? "—"], ["Limit", amount(trade.limitPriceMinor)], ["Status", (trade.status ?? "").toLowerCase() || "—"]]
53	    : [["Shares", trade.shares ?? "—"], [trade.orderType === "limit" ? "Limit price" : "Price", amount(trade.orderType === "limit" ? trade.limitPriceMinor : trade.estimatePriceMinor)],
54	      ["Estimated total", amount(trade.estimatedTotalMinor)], ["Order cost", amount(trade.entryCostMinor)]];
55	
56	  return <section aria-label={`${verb} card`} className="my-3 rounded-xl border border-ai-border bg-ai-soft p-4">
57	    <div className="flex flex-wrap items-center justify-between gap-2">
58	      <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${tone}`}>{trade.action === "cancel" ? "Cancel order" : `${verb} · ${trade.orderType === "limit" ? "limit" : "market"}`}</span>
59	      {open && clock !== null && <span role="timer" aria-live="off" className={`font-mono text-xs tabular-nums ${expired ? "text-danger" : seconds! < 60 ? "text-warning" : "text-muted-foreground"}`}>{expired ? "Preview expired" : `Valid for ${clock}`}</span>}
60	    </div>
61	    <p className="mt-2 font-medium">{trade.name}</p>
62	    {trade.isin && <p className="font-mono text-xs text-muted-foreground">{trade.isin}{trade.venue ? ` · ${trade.venue}` : ""}</p>}
63	    <dl className="mt-3 grid grid-cols-2 gap-3 text-sm sm:grid-cols-4">{figures.map(([label, value]) =>
64	      <div key={label}><dt className="text-xs text-muted-foreground">{label}</dt><dd className="font-mono tabular-nums">{value}</dd></div>)}</dl>
65	    {trade.quote && <p className="mt-2 text-xs text-muted-foreground">Bid {amount(trade.quote.bidMinor)} · ask {amount(trade.quote.askMinor)}{trade.quote.at ? ` · quoted ${dateTime(trade.quote.at)}` : ""}{trade.quote.outdated ? " · market closed, the price can differ when it opens" : ""}</p>}
66	    {trade.wholePosition && <p className="mt-2 text-sm text-warning">This sells your whole position.</p>}
67	    {trade.warnings.length > 0 && <ul className="mt-2 space-y-1 text-sm text-warning">{trade.warnings.map(warning => <li key={warning}>{warning}</li>)}</ul>}
68	    {trade.review && <details className="mt-3 text-sm"><summary className="cursor-pointer text-muted-foreground hover:text-foreground">Scalable&apos;s full review</summary>
69	      <pre className="mt-2 max-h-72 overflow-auto whitespace-pre-wrap rounded-lg border border-border bg-background p-3 font-sans text-xs">{trade.review}</pre>
70	      {trade.kid && <a href={trade.kid.url} target="_blank" rel="noreferrer" className="mt-1 inline-block text-xs text-brand underline">{trade.kid.label}</a>}
