37	        <thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th scope="col" className="py-2 pr-4 font-medium">Date</th><th scope="col" className="py-2 pr-4 font-medium">Expected</th><th scope="col" className="py-2 pr-4 font-medium">Conservative</th><th scope="col" className="py-2 font-medium">Optimistic</th></tr></thead>
38	        <tbody>{days.map(day => <tr key={day.date} className="border-b border-border last:border-0 font-mono"><th scope="row" className="py-1.5 pr-4 text-left font-normal">{day.date}</th><td className="py-1.5 pr-4">{money(day.expectedMinor)}</td><td className="py-1.5 pr-4">{money(day.conservativeMinor)}</td><td className="py-1.5">{money(day.optimisticMinor)}</td></tr>)}</tbody>
39	      </table></div>
40	    </details>
41	  </div>;
