// One timeline for picture and sound, in seconds. The music runs at 120 BPM, so a bar is 2 seconds
// and every scene starts on a bar. scripts/make-audio.mts reads this file to place the sound effects.
export const FPS = 60;
export const BAR = 2;

export const SCENES = {
  hook: { start: 0, seconds: 4 },
  call: { start: 4, seconds: 10 },
  see: { start: 14, seconds: 6 },
  budget: { start: 20, seconds: 4 },
  plan: { start: 24, seconds: 6 },
  build: { start: 30, seconds: 8 },
  trade: { start: 38, seconds: 4 },
  power: { start: 42, seconds: 4 },
  everything: { start: 46, seconds: 4 },
  own: { start: 50, seconds: 7 },
} as const;

export const TOTAL_SECONDS = SCENES.own.start + SCENES.own.seconds;

// Local times inside each scene, shared with the audio so a click lands with its sound.
export const CUES = {
  hookRings: [1.9, 2.5],
  hookAnswer: 3.4,
  callSave: 8.5,
  budgetAdd: 1.5,
  planWhatIf: 2.7,
  buildSend: 1.25,
  buildPageDone: 3.5,
  buildSliderStart: 4.5,
  tradeBuy: 2.75,
  powerSignIn: 1.75,
  everythingFirstTile: 0.05,
  everythingStep: 0.25,
  everythingTiles: 12,
  ownFinal: 3,
};

// Scenes that open with a big word slamming in.
export const SLAM_SCENES = ["call", "see", "budget", "plan", "build", "trade", "power"] as const;

import type { CSSProperties, ReactNode } from "react";
import { Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import { loadFont as loadDisplay } from "@remotion/google-fonts/BricolageGrotesque";
import { loadFont as loadSans } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";

const display = loadDisplay("normal", { weights: ["500", "600", "700"], subsets: ["latin"] }).fontFamily;
const sans = loadSans("normal", { weights: ["400", "500", "600"], subsets: ["latin"] }).fontFamily;
const mono = loadMono("normal", { weights: ["400", "500"], subsets: ["latin"] }).fontFamily;

export const font = { display, sans, mono };

// Moneo's dark theme, copied from app/globals.css.
export const c = {
  bg: "#0f1011",
  card: "#16171a",
  fg: "#eeece6",
  muted: "#1d1e22",
  mutedFg: "#a3a39e",
  subtle: "#85867f",
  border: "#24262a",
  input: "#2a2c30",
  lime: "#cbf26b",
  ai: "#b8a6ff",
  aiSoft: "#1a1922",
  aiBorder: "#3d3760",
  successSoft: "#1c2410",
  warning: "#ff9a76",
  warningSoft: "#2a1b14",
  danger: "#ff7a6b",
  chartOut: "#5b5d62",
};

const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.bezier(0.34, 1.56, 0.64, 1);
export const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);

/** The scene's clock in seconds, so timings survive a change of frame rate. */
export function useT() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  return frame / fps;
}

export const ramp = (t: number, from: number, to: number, easing: (x: number) => number = OUT) =>
  interpolate(t, [from, to], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing });
export const pop = (t: number, at: number, seconds = 0.45) => ramp(t, at, at + seconds, BACK);
export const lerp = (a: number, b: number, p: number) => a + (b - a) * p;

const euros = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR" });
const wholeEuros = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR", maximumFractionDigits: 0 });
export const money = (value: number) => euros.format(value);
export const whole = (value: number) => wholeEuros.format(value);

/** A voice-like level from 0 to 1 that never repeats visibly. */
export const voice = (t: number) => Math.max(0, 0.5 + 0.28 * Math.sin(t * 17) + 0.22 * Math.sin(t * 29 + 1) + 0.16 * Math.sin(t * 7.3 + 2));

/** Rises into place at a time. */
export function Rise({ at, by = 36, seconds = 0.6, style, children }: { at: number; by?: number; seconds?: number; style?: CSSProperties; children: ReactNode }) {
  const t = useT();
  const p = ramp(t, at, at + seconds);
  return <div style={{ ...style, opacity: ramp(t, at, at + seconds * 0.5), transform: `translateY(${(1 - p) * by}px)` }}>{children}</div>;
}

/** Springs into place at a time. */
export function Pop({ at, from = 0.8, style, children }: { at: number; from?: number; style?: CSSProperties; children: ReactNode }) {
  const t = useT();
  return <div style={{ ...style, opacity: ramp(t, at, at + 0.15), transform: `scale(${lerp(from, 1, pop(t, at))})` }}>{children}</div>;
}

/** Each scene zooms in out of a blur and leaves by pushing past the viewer. */
export function Scene({ seconds, children }: { seconds: number; children: ReactNode }) {
  const t = useT();
  const enter = ramp(t, 0, 0.35), exit = ramp(t, seconds - 0.22, seconds, Easing.in(Easing.cubic));
  return <div style={{ position: "absolute", inset: 0, opacity: Math.min(enter, 1 - exit), transform: `scale(${lerp(0.97, 1, enter) + exit * 0.06})`, filter: exit > 0 ? `blur(${exit * 14}px)` : undefined }}>{children}</div>;
}

/** The word that opens a scene: huge in the middle on the beat, then it settles top-left and makes room. */
export function Slam({ word, sub, settle = 0.55 }: { word: string; sub: string; settle?: number }) {
  const t = useT();
  const p = ramp(t, settle, settle + 0.5, IN_OUT);
  const hit = pop(t, 0, 0.3);
  const scale = lerp(lerp(3.5, 2.8, hit), 1, p);
  return <>
    <div style={{ position: "absolute", left: `${lerp(50, 4.7, p)}%`, top: `${lerp(50, 5.5, p)}%`, transformOrigin: "0 0", transform: `translate(${-(1 - p) * 50 * scale}%, ${-(1 - p) * 50 * scale}%) scale(${scale})`, opacity: ramp(t, 0, 0.08), fontFamily: font.display, fontWeight: 600, fontSize: 112, lineHeight: 1, letterSpacing: "-0.04em", color: c.lime, whiteSpace: "nowrap", zIndex: 5 }}>{word}</div>
    <div style={{ position: "absolute", right: 90, top: 66, width: 1130, height: 112, display: "flex", alignItems: "center", justifyContent: "flex-end", textAlign: "right", opacity: ramp(t, settle + 0.25, settle + 0.6), transform: `translateX(${(1 - ramp(t, settle + 0.25, settle + 0.7)) * 30}px)`, fontFamily: font.sans, fontSize: 40, lineHeight: 1.22, letterSpacing: "-0.015em", color: c.mutedFg }}>{sub}</div>
  </>;
}

export function Card({ style, children }: { style?: CSSProperties; children: ReactNode }) {
  return <div style={{ background: c.card, border: `1px solid ${c.border}`, borderRadius: 20, padding: 32, fontFamily: font.sans, color: c.fg, ...style }}>{children}</div>;
}

export function Eyebrow({ style, children }: { style?: CSSProperties; children: ReactNode }) {
  return <div style={{ fontFamily: font.mono, fontSize: 19, letterSpacing: "0.08em", textTransform: "uppercase", color: c.subtle, ...style }}>{children}</div>;
}

/** A pointer that glides between waypoints and ripples where it clicks. */
export function Cursor({ path, clicks = [] }: { path: { t: number; x: number; y: number }[]; clicks?: number[] }) {
  const t = useT();
  const times = path.map(point => point.t);
  const at = (values: number[]) => interpolate(t, times, values, { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: IN_OUT });
  const x = at(path.map(point => point.x)), y = at(path.map(point => point.y));
  const pressed = clicks.some(click => t >= click && t < click + 0.12);
  return <div style={{ position: "absolute", inset: 0, zIndex: 20, pointerEvents: "none", opacity: ramp(t, times[0] - 0.2, times[0]) }}>
    {clicks.map(click => {
      const p = ramp(t, click, click + 0.5);
      return t >= click && p < 1 ? <div key={click} style={{ position: "absolute", left: x - 50, top: y - 50, width: 100, height: 100, borderRadius: "50%", border: `3px solid ${c.lime}`, opacity: 1 - p, transform: `scale(${0.2 + p * 1.2})` }} /> : null;
    })}
    <svg width="44" height="44" viewBox="0 0 24 24" style={{ position: "absolute", left: x - 8, top: y - 6, transform: `scale(${pressed ? 0.82 : 1})`, filter: "drop-shadow(0 6px 10px rgb(0 0 0 / .55))" }}>
      <path d="M5 3l14 8.2-6.1 1.4L9.6 19z" fill="#fff" stroke="#0f1011" strokeWidth="1.3" strokeLinejoin="round" />
    </svg>
  </div>;
}

/** Text that appears word by word from a start time. */
export function Words({ text, at, perWord = 0.16, style }: { text: string; at: number; perWord?: number; style?: CSSProperties }) {
  const t = useT();
  return <div style={style}>{text.split(" ").map((word, index) => {
    const p = ramp(t, at + index * perWord, at + index * perWord + 0.25);
    return <span key={index} style={{ opacity: p, display: "inline-block", transform: `translateY(${(1 - p) * 12}px)`, marginRight: "0.26em" }}>{word}</span>;
  })}</div>;
}

export function typed(text: string, t: number, at: number, perChar = 0.03) {
  return text.slice(0, Math.max(0, Math.floor((t - at) / perChar)));
}

/** A smooth line through points, the same curve for every chart. */
export function smoothPath(points: [number, number][]) {
  let path = `M${points[0][0]},${points[0][1]}`;
  for (let i = 0; i < points.length - 1; i++) {
    const [p0, p1, p2, p3] = [points[Math.max(0, i - 1)], points[i], points[i + 1], points[Math.min(points.length - 1, i + 2)]];
    path += `C${p1[0] + (p2[0] - p0[0]) / 6},${p1[1] + (p2[1] - p0[1]) / 6} ${p2[0] - (p3[0] - p1[0]) / 6},${p2[1] - (p3[1] - p1[1]) / 6} ${p2[0]},${p2[1]}`;
  }
  return path;
}

/** Moneo's call orb, driven by a level and two tones like components/voice-call.tsx. */
export function Orb({ size, level, spin, a, b }: { size: number; level: number; spin: number; a: string; b: string }) {
  const core = size * 0.62;
  return <div style={{ position: "relative", width: size, height: size, display: "grid", placeItems: "center" }}>
    <div style={{ position: "absolute", inset: "2%", borderRadius: "50%", background: `radial-gradient(circle, ${a}, transparent 68%)`, opacity: 0.45, filter: `blur(${size * 0.08}px)`, transform: `scale(${1 + level * 0.5})` }} />
    <div style={{ position: "absolute", inset: "10%", borderRadius: "50%", border: `2px solid ${a}66`, transform: `scale(${1 + level * 0.3})` }} />
    <div style={{ position: "relative", width: core, height: core, borderRadius: "50%", overflow: "hidden", transform: `scale(${1 + level * 0.14})`, boxShadow: `inset 0 -10px 30px rgb(0 0 0 / .18), 0 14px 60px -14px ${a}` }}>
      <div style={{ position: "absolute", inset: "-25%", filter: "blur(10px)", background: `conic-gradient(from ${90 + spin}deg, ${a}, ${b}, ${a})` }} />
      <div style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "radial-gradient(circle at 32% 28%, rgb(255 255 255 / .5), transparent 48%)" }} />
    </div>
  </div>;
}

export function Logo({ size }: { size: number }) {
  return <svg width={size} height={size} viewBox="0 0 192 192" aria-hidden="true">
    <rect width="192" height="192" rx="42" fill="#121314" />
    <path d="M50 142V62q0-11 8-6l38 56 38-56q8-5 8 6v80" fill="none" stroke={c.lime} strokeWidth="20" strokeLinecap="round" strokeLinejoin="round" />
  </svg>;
}

import { registerRoot } from "remotion";
import { Root } from "./Root";

registerRoot(Root);

import { Composition } from "remotion";
import { Promo } from "./Promo";
import { FPS, TOTAL_SECONDS } from "./timeline";

export const Root = () => <Composition id="MoneoPromo" component={Promo} durationInFrames={Math.round(TOTAL_SECONDS * FPS)} fps={FPS} width={1920} height={1080} />;

import type { ComponentType } from "react";
import { AbsoluteFill, Audio, Sequence, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import { c, IN_OUT, ramp } from "./kit";
import { SCENES } from "./timeline";
import { Hook } from "./scenes/Hook";
import { Call } from "./scenes/Call";
import { See } from "./scenes/See";
import { Budget } from "./scenes/Budget";
import { Plan } from "./scenes/Plan";
import { Build } from "./scenes/Build";
import { Trade } from "./scenes/Trade";
import { Power } from "./scenes/Power";
import { Everything } from "./scenes/Everything";
import { Own } from "./scenes/Own";

const parts: [keyof typeof SCENES, ComponentType][] = [["hook", Hook], ["call", Call], ["see", See], ["budget", Budget], ["plan", Plan], ["build", Build], ["trade", Trade], ["power", Power], ["everything", Everything], ["own", Own]];

/** Graphite ground with two slow glows, lime for money and violet for the AI, as in the app. */
function Backdrop() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  return <AbsoluteFill style={{ background: c.bg }}>
    <div style={{ position: "absolute", width: 1300, height: 1300, left: 1000 + Math.sin(t / 5) * 260, top: -560 + Math.cos(t / 4) * 140, background: "radial-gradient(circle, rgb(184 166 255 / .14), transparent 65%)" }} />
    <div style={{ position: "absolute", width: 1300, height: 1300, left: -480 + Math.cos(t / 6) * 240, top: 240 + Math.sin(t / 5) * 140, background: "radial-gradient(circle, rgb(203 242 107 / .08), transparent 65%)" }} />
    <div style={{ position: "absolute", inset: 0, backgroundImage: "radial-gradient(rgb(255 255 255 / .05) 1.2px, transparent 1.2px)", backgroundSize: "44px 44px" }} />
  </AbsoluteFill>;
}

/** A lime panel sweeping across a big cut, timed so the swap happens behind it. */
function Wipe({ at }: { at: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  const inn = ramp(t, at - 0.22, at, IN_OUT), out = ramp(t, at, at + 0.26, IN_OUT);
  if (inn === 0 || out === 1) return null;
  return <div style={{ position: "absolute", inset: 0, background: c.lime, zIndex: 50, transform: `translateX(${(inn - 1) * 100 + out * 100}%)` }} />;
}

export function Promo() {
  const { fps } = useVideoConfig();
  return <AbsoluteFill>
    <Backdrop />
    {parts.map(([name, Part]) => <Sequence key={name} name={name} from={Math.round(SCENES[name].start * fps)} durationInFrames={Math.round(SCENES[name].seconds * fps)}><Part /></Sequence>)}
    <Wipe at={SCENES.call.start} />
    <Wipe at={SCENES.see.start} />
    <Wipe at={SCENES.everything.start} />
    <Audio src={staticFile("moneo-promo-track.wav")} />
  </AbsoluteFill>;
}

import { CheckCircle2, Loader2, Mic, PhoneOff } from "lucide-react";
import { c, Card, Cursor, Eyebrow, font, lerp, Orb, Pop, ramp, Rise, Scene, Slam, useT, voice, Words } from "../kit";
import { CUES, SCENES } from "../timeline";

// Who is speaking when, in scene seconds.
const YOU = { from: 1.05, to: 3.85 }, MONEO = { from: 5.15, to: 8.0 };
const QUESTION = "Can I afford Lisbon in June? Oh, and I just spent 42 euros at Trattoria Da Gino.";
const ANSWER = "Yes. After rent and Lisbon you still end June with €3,180.";

function Task({ at, doneAt, title, working, done }: { at: number; doneAt: number; title: string; working: string; done: string }) {
  const t = useT();
  const finished = t >= doneAt;
  return <Pop at={at} from={0.92}><div style={{ display: "flex", alignItems: "center", gap: 20, minHeight: 92, padding: "12px 24px", borderRadius: 16, border: `1px solid ${c.border}`, background: c.card }}>
    {finished ? <CheckCircle2 size={32} color={c.lime} /> : <Loader2 size={32} color={c.ai} style={{ transform: `rotate(${t * 360}deg)` }} />}
    <div><div style={{ fontSize: 28, fontWeight: 500 }}>{title}</div><div style={{ fontSize: 23, color: c.mutedFg }}>{finished ? done : working}</div></div>
  </div></Pop>;
}

export function Call() {
  const t = useT();
  const talkingYou = t > YOU.from && t < YOU.to, talkingMoneo = t > MONEO.from && t < MONEO.to;
  const thinking = t >= YOU.to && t <= MONEO.from;
  const tone = talkingMoneo ? [c.lime, "#7fa63a"] : thinking ? [c.ai, c.lime] : [c.ai, c.aiBorder];
  const label = talkingMoneo ? "Moneo is talking" : thinking ? "Working on it" : "Listening";
  const running = (t < 4.7 ? 1 : 0) + (t < 5.5 ? 1 : 0);
  const saved = t >= CUES.callSave;
  const panel = ramp(t, 0.7, 1.15);
  return <Scene seconds={SCENES.call.seconds}>
    <Slam word="Call it." sub="Talk to your money. It handles everything you ask at once." />
    <div style={{ position: "absolute", left: 90, top: 200, width: 760, height: 800, display: "flex", flexDirection: "column", alignItems: "center", opacity: panel }}>
      <Orb size={430} level={talkingYou || talkingMoneo ? voice(t) : 0.08} spin={t * 75} a={tone[0]} b={tone[1]} />
      <div style={{ fontFamily: font.display, fontSize: 40, fontWeight: 500, color: c.fg, marginTop: -6 }}>{label}</div>
      <div style={{ position: "relative", width: "100%", marginTop: 34, height: 250, textAlign: "center" }}>
        {t < MONEO.from - 0.25
          ? <div style={{ opacity: 1 - ramp(t, MONEO.from - 0.5, MONEO.from - 0.25) }}><Eyebrow>You</Eyebrow><Words text={QUESTION} at={YOU.from} perWord={0.155} style={{ marginTop: 10, fontFamily: font.sans, fontSize: 44, lineHeight: 1.22, letterSpacing: "-0.02em", color: c.fg }} /></div>
          : <div><Eyebrow style={{ color: c.lime }}>Moneo</Eyebrow><Words text={ANSWER} at={MONEO.from} perWord={0.2} style={{ marginTop: 10, fontFamily: font.sans, fontSize: 50, lineHeight: 1.2, letterSpacing: "-0.02em", color: c.fg, fontWeight: 500 }} /></div>}
      </div>
    </div>
    <div style={{ position: "absolute", left: 900, top: 200, width: 930, height: 800, fontFamily: font.sans, color: c.fg, opacity: panel, transform: `translateX(${(1 - panel) * 50}px)` }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingBottom: 22, borderBottom: `1px solid ${c.border}` }}>
        <div style={{ fontFamily: font.display, fontSize: 36, fontWeight: 600 }}>Call with Moneo</div>
        <div style={{ display: "flex", alignItems: "center", gap: 10, background: c.successSoft, color: c.lime, padding: "8px 18px", borderRadius: 99, fontSize: 24, fontWeight: 500 }}><span style={{ width: 10, height: 10, borderRadius: "50%", background: c.lime, opacity: 0.5 + Math.sin(t * 6) * 0.5 }} />Live</div>
      </div>
      <Eyebrow style={{ marginTop: 26, marginBottom: 14, opacity: ramp(t, 2.0, 2.2) }}>{running ? `Working on ${running} of 2` : "All done"}</Eyebrow>
      <div style={{ display: "grid", gap: 12 }}>
        <Task at={2.05} doneAt={5.5} title="Can I afford Lisbon in June?" working="Reading your forecast…" done="Answered from your records" />
        <Task at={3.1} doneAt={4.7} title="€42 at Trattoria Da Gino" working="Making a card…" done="Waiting for your tap" />
      </div>
      <Rise at={4.75} style={{ marginTop: 26 }}>
        <Eyebrow style={{ marginBottom: 12 }}>Tap to save · nothing is saved until you do</Eyebrow>
        <Card style={{ background: c.aiSoft, borderColor: c.aiBorder, padding: 28 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
            <div style={{ fontSize: 30, fontWeight: 500 }}>Trattoria Da Gino</div>
            <div style={{ fontFamily: font.mono, fontSize: 32 }}>−€42.00</div>
          </div>
          <div style={{ fontSize: 24, color: c.mutedFg, marginTop: 6 }}>Eating out · Revolut · today</div>
          {saved
            ? <Pop at={CUES.callSave} from={0.9} style={{ display: "flex", alignItems: "center", gap: 12, marginTop: 22, height: 60, fontSize: 28, color: c.lime }}><CheckCircle2 size={30} /> Saved to your ledger <span style={{ color: c.mutedFg, textDecoration: "underline", marginLeft: 8 }}>Undo</span></Pop>
            : <div style={{ display: "flex", gap: 14, marginTop: 22 }}>
              <div style={{ height: 60, padding: "0 34px", background: c.lime, color: c.bg, borderRadius: 12, fontSize: 26, fontWeight: 600, display: "grid", placeItems: "center", transform: `scale(${lerp(1, 0.94, ramp(t, CUES.callSave - 0.1, CUES.callSave))})` }}>Save</div>
              <div style={{ height: 60, padding: "0 30px", border: `1px solid ${c.border}`, borderRadius: 12, fontSize: 26, display: "grid", placeItems: "center" }}>Dismiss</div>
            </div>}
        </Card>
      </Rise>
      <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, display: "flex", justifyContent: "center", gap: 24, opacity: ramp(t, 1.2, 1.6) }}>
        <div style={{ width: 76, height: 76, borderRadius: "50%", background: c.muted, display: "grid", placeItems: "center" }}><Mic size={32} /></div>
        <div style={{ width: 76, height: 76, borderRadius: "50%", background: c.danger, display: "grid", placeItems: "center" }}><PhoneOff size={32} color={c.bg} /></div>
      </div>
    </div>
    <Cursor path={[{ t: 7.6, x: 1650, y: 1000 }, { t: CUES.callSave, x: 985, y: 763 }, { t: 9.7, x: 1050, y: 870 }]} clicks={[CUES.callSave]} />
  </Scene>;
}

import { ArrowLeftRight, CreditCard, LayoutGrid, Repeat, Sparkles, Target, TrendingUp, type LucideIcon } from "lucide-react";
import { c, Card, Eyebrow, font, IN_OUT, lerp, money, Pop, ramp, Scene, Slam, smoothPath, useT, whole } from "../kit";
import { SCENES } from "../timeline";

const RAIL: [string, LucideIcon][] = [["Overview", LayoutGrid], ["Transactions", ArrowLeftRight], ["Accounts", CreditCard], ["Recurring", Repeat], ["Plan", Target], ["Wealth", TrendingUp], ["AI", Sparkles]];
const WORTH = [131, 134, 133, 138, 142, 141, 147, 152, 151, 158, 163, 161, 168, 173, 178, 184.3];
const ACCOUNTS: [string, string, number][] = [["Scalable Capital", "Investments", 142860.4], ["Commerzbank", "Savings", 28400], ["Revolut", "Checking", 6420.15], ["Cash", "Wallet", 240]];
const WAITING = ["3 new subscriptions spotted", "Rent is due on the 1st", "Review 14 synced transactions"];
const SYNCS: [string, string, number][] = [["Revolut", "Synced · 14 new", 2.9], ["Commerzbank", "Synced · 6 new", 3.25], ["october-statement.csv", "Imported · 212 rows · Undo", 3.6], ["Scalable Capital", "Portfolio up to date", 3.95]];
const TOTAL = ACCOUNTS.reduce((sum, [, , value]) => sum + value, 0);

function NetWorth({ t }: { t: number }) {
  const reveal = ramp(t, 0.9, 2.3, IN_OUT);
  const points = WORTH.map((value, index): [number, number] => [index * (800 / (WORTH.length - 1)), 200 - (value - 125) * 3.1]);
  const line = smoothPath(points);
  return <Card style={{ gridColumn: "span 2", padding: 36, height: 470 }}>
    <Eyebrow>Net worth</Eyebrow>
    <div style={{ fontFamily: font.display, fontSize: 104, fontWeight: 500, letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums", marginTop: 8, lineHeight: 1.05 }}>{money(TOTAL * lerp(0.72, 1, reveal))}</div>
    <div style={{ fontFamily: font.mono, fontSize: 24, color: c.lime, marginTop: 4 }}>+{whole(53300 * reveal)} in 15 months</div>
    <svg viewBox="0 0 800 200" style={{ width: "100%", height: 200, marginTop: 8, overflow: "visible" }}>
      <defs><linearGradient id="worth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={c.lime} stopOpacity=".32" /><stop offset="1" stopColor={c.lime} stopOpacity="0" /></linearGradient><clipPath id="worthClip"><rect width={800 * reveal} height="240" y="-20" /></clipPath></defs>
      <g clipPath="url(#worthClip)">
        <path d={`${line}L800,200L0,200Z`} fill="url(#worth)" />
        <path d={line} fill="none" stroke={c.lime} strokeWidth="4" strokeLinecap="round" />
      </g>
    </svg>
  </Card>;
}

