      </div>
      <div style={{ flex: 1, padding: 26, display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 18, alignContent: "start", width: 1520 }}>
        <Pop at={0.85} from={0.96} style={{ gridColumn: "span 2" }}><NetWorth t={t} /></Pop>
        <Pop at={1.15} from={0.94}><Card style={{ height: 470, background: c.aiSoft, borderColor: c.aiBorder, padding: 30 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, color: c.ai, fontSize: 26, fontWeight: 500 }}><Sparkles size={24} />Waiting for you</div>
