// Synthesizes the whole soundtrack from code, so the video carries no licensed music:
// a 120 BPM track shaped to the scenes, plus clicks and hits placed from src/timeline.ts.
import { mkdirSync, writeFileSync } from "node:fs";
import { CUES, SCENES, SLAM_SCENES, TOTAL_SECONDS } from "../src/timeline.ts";

const RATE = 44100, BEAT = 0.5, LENGTH = Math.ceil((TOTAL_SECONDS + 0.5) * RATE);
const left = new Float32Array(LENGTH), right = new Float32Array(LENGTH);
const midi = (note: number) => 440 * 2 ** ((note - 69) / 12);
let seed = 7;
const noise = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 2147483648 - 1; };

function add(at: number, seconds: number, make: (time: number, index: number) => number, gain = 1, pan = 0) {
  const start = Math.round(at * RATE), count = Math.round(seconds * RATE);
  for (let i = 0; i < count && start + i < LENGTH; i++) {
    if (start + i < 0) continue;
    const value = make(i / RATE, i) * gain;
    left[start + i] += value * (1 - Math.max(0, pan));
    right[start + i] += value * (1 + Math.min(0, pan));
  }
}

const kick = (at: number, gain: number) => add(at, 0.32, time => Math.sin(2 * Math.PI * (48 * time + 18 * (1 - Math.exp(-time * 28)))) * Math.exp(-time * 10), gain);
const hat = (at: number, gain: number, pan: number) => { let last = 0; add(at, 0.06, time => { const n = noise(), high = n - last; last = n; return high * Math.exp(-time * 70); }, gain, pan); };
const clap = (at: number, gain: number) => { let lp = 0; add(at, 0.18, time => { const n = noise(); lp += (n - lp) * 0.5; return (n - lp) * Math.exp(-time * 24); }, gain); };
const saw = (phase: number) => 2 * (phase - Math.floor(phase + 0.5));
const bass = (at: number, note: number, gain: number) => add(at, BEAT * 0.45, time => { const f = midi(note); return (Math.sin(2 * Math.PI * f * time) + 0.3 * Math.sin(4 * Math.PI * f * time)) * Math.min(1, time * 200) * Math.exp(-time * 3.5); }, gain);
function pluck(at: number, note: number, gain: number, pan: number) {
  let lp = 0;
  add(at, 0.45, time => { lp += (saw(midi(note) * time) * 0.7 + saw(midi(note) * 1.004 * time) * 0.3 - lp) * (0.04 + 0.5 * Math.exp(-time * 16)); return lp * Math.min(1, time * 500) * Math.exp(-time * 7); }, gain, pan);
}
function pad(at: number, seconds: number, notes: number[], gain: number) {
  notes.forEach((note, voice) => {
    let lp = 0;
    const pan = voice % 2 ? 0.35 : -0.35;
    add(at, seconds + 0.15, time => {
      const f = midi(note);
      lp += (saw(f * time) + saw(f * 1.006 * time) - lp) * 0.035;
      return lp * Math.min(1, time * 4, (seconds + 0.15 - time) * 7);
    }, gain, pan);
  });
}
function riser(end: number, seconds: number, gain: number) {
  let lp = 0;
  add(end - seconds, seconds, time => { const p = time / seconds; lp += (noise() - lp) * (0.01 + p * p * 0.5); return lp * p * p; }, gain);
}
const whoosh = (at: number, gain: number) => { let lp = 0; add(at, 0.5, time => { lp += (noise() - lp) * (0.3 * Math.exp(-time * 6) + 0.02); return lp * Math.exp(-time * 6); }, gain); };
const slam = (at: number, gain: number) => {
  add(at, 0.5, time => Math.sin(2 * Math.PI * (38 * time + 12 * (1 - Math.exp(-time * 20)))) * Math.exp(-time * 7), gain);
  let lp = 0; add(at, 0.14, time => { const n = noise(); lp += (n - lp) * 0.4; return lp * Math.exp(-time * 26); }, gain * 0.45);
};
const click = (at: number, gain = 0.5) => add(at, 0.035, time => (Math.sin(2 * Math.PI * 2100 * time) + noise() * 0.4) * Math.exp(-time * 170), gain);
function chime(at: number, gain = 0.2) {
  [84, 91].forEach((note, index) => add(at + index * 0.08, 0.7, time => (Math.sin(2 * Math.PI * midi(note) * time) + 0.3 * Math.sin(4 * Math.PI * midi(note) * time)) * Math.exp(-time * 6), gain));
}
function ringTone(at: number) {
  [76, 72].forEach((note, index) => add(at + index * 0.14, 0.5, time => (Math.sin(2 * Math.PI * midi(note) * time) + 0.25 * Math.sin(6 * Math.PI * midi(note) * time)) * Math.exp(-time * 7), 0.17));
}

// Am F C G, one bar each.
const CHORDS = [[57, 60, 64, 69], [53, 57, 60, 65], [48, 55, 60, 64], [55, 59, 62, 67]];
const ROOTS = [33, 29, 36, 31];
// How much of each part plays at a time, following the story.
const section = (time: number) => {
  if (time < 4) return { kick: 0, bass: 0, hat: 0, clap: 0, arp: time < 2 ? 0 : 0.5, pad: 0.5 };
  if (time < 14) return { kick: 0.6, bass: 0.5, hat: 0.3, clap: 0, arp: 0.5, pad: 0.55 };
  if (time < 42) return { kick: 1, bass: 1, hat: 1, clap: 1, arp: 1, pad: 0.8 };
  if (time < 46) return { kick: 0, bass: 0.55, hat: 0.4, clap: 0, arp: 0.9, pad: 1 };
  if (time < 50) return { kick: 1, bass: 1, hat: 1.2, clap: 1, arp: 1.1, pad: 0.9 };
  if (time < 53) return { kick: 0.8, bass: 0.8, hat: 0.5, clap: 0.6, arp: 0.7, pad: 1 };
  return { kick: 0, bass: 0, hat: 0, clap: 0, arp: 0, pad: 0 };
};

const pulses: number[] = [];
for (let bar = 0; bar * 2 < 53; bar++) {
  const time = bar * 2, chord = CHORDS[bar % 4], root = ROOTS[bar % 4], mix = section(time);
  pad(time, 2, chord, 0.016 * mix.pad);
  for (let step = 0; step < 16; step++) {
    const at = time + step * BEAT / 4, s = section(at);
    if (step % 4 === 0 && s.kick) { kick(at, 0.6 * s.kick); pulses.push(at); }
    if (step % 8 === 4 && s.clap) clap(at, 0.16 * s.clap);
    if (step % 4 === 2 && s.hat) hat(at, 0.13 * s.hat, step % 8 === 2 ? -0.2 : 0.2);
    if (step % 2 === 1 && s.hat) hat(at, 0.04 * s.hat, 0.3);
    if (step % 2 === 0 && step % 4 !== 0 && s.bass) bass(at, root, 0.3 * s.bass);
    if ((step === 3 || step === 11) && s.bass) bass(at, root + 12, 0.16 * s.bass);
    if (step % 2 === 0 && s.arp) {
      const pattern = [0, 2, 3, 1, 2, 3, 1, 3], note = chord[pattern[step / 2]] + 12;
      const pan = step % 4 === 0 ? -0.3 : 0.3;
      pluck(at, note, 0.055 * s.arp, pan);
      pluck(at + 0.375, note, 0.018 * s.arp, -pan); // a dotted-eighth echo
    }
  }
}
// Duck everything but the kick under each kick, for the pump.
const envelope = new Float32Array(LENGTH).fill(1);
for (const at of pulses) {
  const start = Math.round(at * RATE);
  for (let i = 0; i < RATE * 0.3 && start + i < LENGTH; i++) envelope[start + i] = Math.min(envelope[start + i], 0.45 + 0.55 * Math.min(1, i / (RATE * 0.26)));
}
for (let i = 0; i < LENGTH; i++) { left[i] *= envelope[i]; right[i] *= envelope[i]; }

// Story moments, placed after the ducking so they cut through.
riser(SCENES.call.start, 1.2, 0.22);
riser(SCENES.see.start, 3.5, 0.42);
riser(SCENES.everything.start, 2, 0.36);
CUES.hookRings.forEach(ringTone);
click(CUES.hookAnswer);
for (const name of SLAM_SCENES) slam(SCENES[name].start, name === "see" ? 0.7 : 0.5);
slam(SCENES.everything.start, 0.65);
slam(SCENES.own.start, 0.7);
for (const scene of [SCENES.call, SCENES.see, SCENES.budget, SCENES.plan, SCENES.build, SCENES.trade, SCENES.power, SCENES.own]) whoosh(scene.start - 0.12, 0.2);
for (const [scene, at] of [[SCENES.call, CUES.callSave], [SCENES.trade, CUES.tradeBuy], [SCENES.power, CUES.powerSignIn], [SCENES.build, CUES.buildPageDone]] as const) { click(scene.start + at); chime(scene.start + at + 0.03); }
click(SCENES.plan.start + CUES.planWhatIf);
click(SCENES.build.start + CUES.buildSliderStart + 0.2);
for (let i = 0; i < CUES.everythingTiles; i++) click(SCENES.everything.start + CUES.everythingFirstTile + i * CUES.everythingStep, 0.34);

// The ending: one held C-major-add9 chord that rings out over the logo.
const finale = SCENES.own.start + CUES.ownFinal;
slam(finale, 0.6);
pad(finale, 4, [48, 55, 60, 62, 64, 67, 72], 0.024);
[72, 76, 79, 84].forEach((note, index) => add(finale + index * 0.09, 3.2, time => Math.sin(2 * Math.PI * midi(note) * time) * Math.exp(-time * 1.6), 0.07, index % 2 ? 0.3 : -0.3));

// Soft-clip, fade the tail and write 16-bit stereo.
const data = Buffer.alloc(LENGTH * 4);
for (let i = 0; i < LENGTH; i++) {
  const fade = Math.min(1, (LENGTH - i) / (RATE * 1.2));
  data.writeInt16LE(Math.round(Math.tanh(left[i] * 1.2) * fade * 30000), i * 4);
  data.writeInt16LE(Math.round(Math.tanh(right[i] * 1.2) * fade * 30000), i * 4 + 2);
}
const header = Buffer.alloc(44);
header.write("RIFF", 0); header.writeUInt32LE(36 + data.length, 4); header.write("WAVEfmt ", 8); header.writeUInt32LE(16, 16);
header.writeUInt16LE(1, 20); header.writeUInt16LE(2, 22); header.writeUInt32LE(RATE, 24); header.writeUInt32LE(RATE * 4, 28);
header.writeUInt16LE(4, 32); header.writeUInt16LE(16, 34); header.write("data", 36); header.writeUInt32LE(data.length, 40);
mkdirSync("public", { recursive: true });
writeFileSync("public/moneo-promo-track.wav", Buffer.concat([header, data]));
console.log(`Wrote public/moneo-promo-track.wav, ${(LENGTH / RATE).toFixed(1)}s`);

